import{_ as a,o as r,c as o,a2 as t}from"./chunks/framework.BTLSZHNB.js";const u=JSON.parse('{"title":"WorkerVersion — takoform_worker_version","description":"","frontmatter":{},"headers":[],"relativePath":"proposals/edge/worker-version.md","filePath":"proposals/edge/worker-version.md"}'),i={name:"proposals/edge/worker-version.md"};function s(n,e,d,c,l,h){return r(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="workerversion-—-takoform-worker-version" tabindex="-1">WorkerVersion — <code>takoform_worker_version</code> <a class="header-anchor" href="#workerversion-—-takoform-worker-version" aria-label="Permalink to &quot;WorkerVersion — `takoform_worker_version`&quot;">​</a></h1><h2 id="workload-and-consumer" tabindex="-1">Workload and consumer <a class="header-anchor" href="#workload-and-consumer" aria-label="Permalink to &quot;Workload and consumer&quot;">​</a></h2><p>A team ships one executable snapshot of a worker: which bundle runs, which handlers it exports, its non-secret vars, and the typed capability bindings its code may use. Deployments select among versions; nothing ever edits a version in place.</p><h2 id="role" tabindex="-1">Role <a class="header-anchor" href="#role" aria-label="Permalink to &quot;Role&quot;">​</a></h2><p><code>revision</code>. Every field is immutable; a change is a new Worker Version.</p><h2 id="observable-semantics" tabindex="-1">Observable semantics <a class="header-anchor" href="#observable-semantics" aria-label="Permalink to &quot;Observable semantics&quot;">​</a></h2><p>The runtime a version runs on is not a field of this Form. It is the exact <code>worker.runtime@1.0.0</code> contract the <a href="./module-worker.html">ModuleWorker</a> identity provides, so there is no <code>compatibilityDate</code> and no <code>compatibilityFlags</code> (<a href="./../../spec/decisions/0019-the-module-worker-abi-is-an-exact-contract.html">decision 0019</a>): a date names no behavior without a registry saying what each date changes, and two hosts reading the same date could legitimately run different runtimes.</p><p><code>handlers</code> closes the event surface a host may attach to, and its vocabulary IS the handler set that contract defines — a host refuses a handler the contract does not define, before any mutation. <code>vars</code> is a bounded data-only JSON map projected into the module environment. Each binding list projects one exact Binding contract — edge KV, object bucket, SQLite, queue producer, service — under a JavaScript identifier name, and each of those contracts states the JavaScript surface it projects, not just the operations it grants. <code>requiredSensitiveVars</code> declares only the names of sealed values the host must supply; values never enter portable state.</p><p>The field is named <code>requiredSensitiveVars</code>, not <code>secretRequirements</code>, because the Form Package data-only policy forbids the token <code>secret</code> in any field name (<code>formpackage</code> rejects the whole definition rather than the value), so the declaration states the same fact in permitted vocabulary.</p><h2 id="deferred-a-runtime-revision" tabindex="-1">Deferred: a runtime revision <a class="header-anchor" href="#deferred-a-runtime-revision" aria-label="Permalink to &quot;Deferred: a runtime revision&quot;">​</a></h2><p>A future runtime revision is a new exact <code>worker.runtime</code> version, published at its own digest. If it changes what this Form desires it is also a new definition version of this Form. It is never a new value of a date field, and never a flag.</p><h2 id="deferred-static-assets" tabindex="-1">Deferred: static assets <a class="header-anchor" href="#deferred-static-assets" aria-label="Permalink to &quot;Deferred: static assets&quot;">​</a></h2><p>This milestone has no <code>assets</code> field. Static assets served alongside a worker are the separate <code>StaticAssetBundle</code> Form of a later milestone (<code>spec/form-families.md</code>); <code>WorkerVersion</code> gains an <code>assets</code> reference to it when that Form lands, as one new optional field on a new definition version. Until then this Form cannot express an asset-serving worker, and no host should infer one.</p><h2 id="why-this-is-one-form" tabindex="-1">Why this is one Form <a class="header-anchor" href="#why-this-is-one-form" aria-label="Permalink to &quot;Why this is one Form&quot;">​</a></h2><p>Code, runtime behavior, and granted capabilities must travel as one immutable unit, or rollback cannot be exact: re-activating an old version must restore exactly the bindings and configuration it was verified with.</p><h2 id="what-would-require-a-separate-form" tabindex="-1">What would require a separate Form <a class="header-anchor" href="#what-would-require-a-separate-form" aria-label="Permalink to &quot;What would require a separate Form&quot;">​</a></h2><p>Mutable in-place configuration, a per-environment overlay model, or bindings resolved at request time each break the immutable-snapshot shape.</p><h2 id="provided-interfaces" tabindex="-1">Provided Interfaces <a class="header-anchor" href="#provided-interfaces" aria-label="Permalink to &quot;Provided Interfaces&quot;">​</a></h2><p>None. Both of the worker&#39;s exact contracts — <code>worker.runtime@1.0.0</code> and <code>worker.service@1.0.0</code> — belong to the <a href="./module-worker.html">ModuleWorker</a> identity: a <code>module-worker.service</code> binding addresses a worker by logical identity, and the runtime ABI is what a host implements rather than what one snapshot ships.</p><h2 id="accepted-bindings" tabindex="-1">Accepted Bindings <a class="header-anchor" href="#accepted-bindings" aria-label="Permalink to &quot;Accepted Bindings&quot;">​</a></h2><p><code>module-worker.edge-kv</code>, <code>module-worker.object-bucket</code>, <code>module-worker.sqlite</code>, <code>module-worker.queue-producer</code>, <code>module-worker.service</code>, each at 1.0.0 with its exact schema digest.</p><h2 id="lifecycle-risks" tabindex="-1">Lifecycle risks <a class="header-anchor" href="#lifecycle-risks" aria-label="Permalink to &quot;Lifecycle risks&quot;">​</a></h2><p>Creating a version whose binding targets are absent must fail; deleting a bound target must fail with <code>dependency_in_use</code> (refuse_while_bound). Deleting a version still weighted by a deployment must fail. Import must reproduce the exact snapshot, including binding names.</p><h2 id="prior-art" tabindex="-1">Prior art <a class="header-anchor" href="#prior-art" aria-label="Permalink to &quot;Prior art&quot;">​</a></h2><p>The versioned worker snapshot of a proven edge platform, with its binding environment made an exact digest-bound contract per decision 0010. The sensitive-value declaration mirrors that platform&#39;s sealed secret path while keeping only names portable.</p>',25)])])}const p=a(i,[["render",s]]);export{u as __pageData,p as default};
